void *regex_new(const uint8_t*pattern,size_t size) {
 int error;PCRE2_SIZE offset;regex_t*r=malloc(sizeof(*r));if(!r)abort();
 r->code=pcre2_compile(pattern,size,0,&error,&offset,NULL);if(!r->code)abort();
