        (regex: "<[^>]*>",            replacement: "|"),
        (regex: "\\|[^|][^|]*\\|",    replacement: "-")
        ].reduce(sequence) { buffer, iub in
            return buffer.replacingOccurrences(of: iub.regex, 
                with: iub.replacement, options: .regularExpression)
    }.utf8.count
    group.leave()
}

