    end
    checksum = checksum+sign*flips;
    maximum = max(maximum,flips);
    sign = -sign;
    while true
        if r == n
            fprintf('%d\nPfannkuchen(%d) = %d\n',checksum,n,maximum);
            return;
        end
        first = p(1);
        for pos = 1:r
            p(pos) = p(pos+1);
        end
        p(r+1) = first;
        count(r+1) = count(r+1)-1;
        if count(r+1) > 0
            break;
        end
        r = r+1;
    end
end
end

