const Output = struct {
    fn write(_: Output, bytes: []const u8) !usize {
        try output_writer.interface.writeAll(bytes);
        return bytes.len;
    }
    fn writeByte(self: Output, byte: u8) !void {
        _ = try self.write(&.{byte});
    }
    fn print(_: Output, comptime format: []const u8, args: anytype) !void {
        try output_writer.interface.print(format, args);
    }
};


const max_line_length = 60;

const im = 139968;
const ia = 3877;
const ic = 29573;
var seed: u32 = 42;
fn nextRandom(max: f64) f64 {
    seed = (seed * ia + ic) % im;
    return max * @as(f64, @floatFromInt(seed)) / @as(f64, @floatFromInt(im));
}

const AminoAcid = struct {
    l: u8,
    p: f64,
};

fn repeatAndWrap(out: anytype, comptime sequence: []const u8, count: usize) void {
    var padded_sequence: [sequence.len + max_line_length]u8 = undefined;
    for (&padded_sequence, 0..) |*e, i| {
        e.* = sequence[i % sequence.len];
    }

    var off: usize = 0;
    var idx: usize = 0;
    while (idx < count) {
        const rem = count - idx;
        const line_length = @min(@as(usize, max_line_length), rem);

        _ = out.write(padded_sequence[off .. off + line_length]) catch unreachable;
        _ = out.writeByte('\n') catch unreachable;

        off += line_length;
        if (off > sequence.len) {
            off -= sequence.len;
        }
        idx += line_length;
    }
}

fn generateAndWrap(out: anytype, comptime nucleotides: []const AminoAcid, count: usize) void {
    var cum_prob: f64 = 0;
    var cum_prob_total: [nucleotides.len]f64 = undefined;
    for (nucleotides, 0..) |n, i| {
        cum_prob += n.p;
        cum_prob_total[i] = cum_prob;
    }

    var line: [max_line_length + 1]u8 = undefined;
    line[max_line_length] = '\n';

    var idx: usize = 0;
    while (idx < count) {
        const rem = count - idx;
        const line_length = @min(@as(usize, max_line_length), rem);

        for (line[0..line_length]) |*col| {
            const r = nextRandom(1.0);

            var c: usize = 0;
            for (cum_prob_total) |n| {
                if (n <= r) {
                    c += 1;
                }
            }

            col.* = nucleotides[c].l;
        }

        line[line_length] = '\n';
        _ = out.write(line[0 .. line_length + 1]) catch unreachable;
        idx += line_length;
    }
}

var buffer: [256]u8 = undefined;
var fixed_allocator = std.heap.FixedBufferAllocator.init(buffer[0..]);
var allocator = &fixed_allocator.allocator();

pub fn main(init: std.process.Init) !void {
    process_args = init.minimal.args;
    process_io = init.io;
