        });
        if (i == 0) break;
    }
    try stdout.print("\n", .{});
}

fn printOcc(s: []const u8, map: *Map) !void {
    const count = if (map.get(Code.fromStr(s))) |x| x else 0;
    try stdout.print("{}\t{s}\n", .{ count, s });
}

pub fn main(init: std.process.Init) !void {
