fn scale(v: vec3, f: f64) vec3 {
    return v * @as(vec3, @splat(f));
}
fn length_sq(v: vec3) f64 {
    return dot(v, v);
}
fn length(v: vec3) f64 {
    return math.sqrt(length_sq(v));
}

