    var e: f64 = 0.0;
    for (bodies, 0..) |bi, i| {
        e += 0.5 * length_sq(bi.vel) * bi.mass;
        for (bodies[i + 1 ..]) |bj| {
            e -= bi.mass * bj.mass / length(bi.pos - bj.pos);
        }
