static void randomFasta(String seq, double[] probability, int n) {
   int len = seq.Length;
   int i, j;
   var b = new StringBuilder();   
   for (i=0; i<n; i++) {
      double v = fastaRand(1.0);        
      /* slowest idiomatic linear lookup.  Fast if len is short though. */
      for (j=0; j<len-1; j++) {  
