  end if;

  mpz_init(Tmp1);
  mpz_init(Tmp2);

  mpz_init_set_ui(Acc, 0);
  mpz_init_set_ui(Den, 1);
  mpz_init_set_ui(Num, 1);

  declare
    use Interfaces.C;
    D, D4, K, I : Interfaces.C.unsigned := 0;
    Space   : constant Interfaces.C.unsigned := 32;
  begin
    <<Work_Loop>>
    while I < N loop
      K := K + 1;
      Consume(K);

      if mpz_cmp(Num,Acc)>0 then goto Work_Loop; end if;
      D := Extract(3);
      D4 := Extract(4);
      if D /= D4 then 
        goto Work_Loop;
      end if;

      Put_Char(D + 48);
      I := I + 1;
      if I rem 10 = 0 then
        Put(ASCII.HT & ":"); Count_IO.Put(I,Width=>0); New_Line;
      end if;
      Eliminate(D);

    end loop;
    if I rem 10 /= 0 then
       for X in 1 .. 10 - Integer'Val (I) rem 10 loop
          Put_Char (Space);
       end loop;
       Put(ASCII.HT & ":"); Count_IO.Put(I,Width=>0); New_Line;
    end if;
  end;

end Pidigits;

