      zr = zi = tr = ti = 0.0;
      cr = 2.0 * x / w - 1.5;
      ci = 2.0 * y / h - 1.0;
      for (int i = 0; i < iter && (tr + ti <= limit * limit); ++i) {
        zi = 2.0 * zr * zi + ci;
        zr = tr - ti + cr;
        tr = zr * zr;
        ti = zi * zi;
      }

      byte_acc[0] <<= 1;
      if (tr + ti <= limit * limit) byte_acc[0] |= 0x01;
      ++bit_num;

      if (bit_num == 8) {
        stdout.add(byte_acc);
        byte_acc[0] = 0;
        bit_num = 0;
      } else if (x == w - 1) {
        byte_acc[0] <<= (8 - w % 8);
        stdout.add(byte_acc);
        byte_acc[0] = 0;
        bit_num = 0;
      }
    }

  }
}

