    tuple(ctRegex!("agggta[cgt]a|t[acg]taccct"),"agggta[cgt]a|t[acg]taccct"),
    tuple(ctRegex!("agggtaa[cgt]|[acg]ttaccct"),"agggtaa[cgt]|[acg]ttaccct")
];

static immutable s2 = [
    ctRegex!("tHa[Nt]"),
    ctRegex!("aND|caN|Ha[DS]|WaS"),
    ctRegex!("a[NSt]|BY"), 
    ctRegex!("<[^>]*>"),
    ctRegex!("\\|[^|][^|]*\\|"),
];

