        auto sequenceStart = min(headerEnd+1,input.length);
        auto sequenceEnd = sequenceStart;
        while (sequenceEnd < input.length && input[sequenceEnd] != '>')
            sequenceEnd++;
        size_t column;
        for (auto i=sequenceEnd; i > sequenceStart;) {
            auto c = input[--i];
