    True -> Nil
    False -> {
      io.write(io.bytes(row(n, y, 0, 0, 0, [])))
      rows(n, y + 1)
    }
  }
}

pub fn main() -> Nil {
  let n = io.argument()
  io.text("P4\n" <> io.integer(n) <> " " <> io.integer(n) <> "\n")
