fn digits(n: Int, q: Int, r: Int, t: Int, k: Int, printed: Int, line: String) -> Nil {
  case printed == n {
    True -> Nil
    False -> {
      let numerator3 = 3 * q + r
      let numerator4 = 4 * q + r
      let digit3 = numerator3 / t
      let digit4 = numerator4 / t
      case digit3 == digit4 {
