            }
            False -> line
          }
          digits(n, q * 10, { r - digit3 * t } * 10, t, k, printed, line)
        }
        False -> {
          let factor = 2 * k + 1
          digits(n, q * k, { 2 * q + r } * factor, t * factor, k + 1, printed, line)
        }
      }
    }
  }
}

